// Original peripheral windows; never fabricate server friends, seasons or collected cards.
export class AuxiliaryUI{
 constructor(host,assets){this.host=host;this.ui=host.ui;this.assets=assets;}
 friends(tab='friends'){const page=tab==='timeline'?'3':tab==='rank'?'4':'0',v=this.host.show('FriendMainWindow',{controllers:{c1:page,ctrl_platform:'0',ctrl_wxIsAuth:'0'}},'friends');for(const list of v.querySelectorAll('.fg-list'))list.replaceChildren();for(const name of ['btn_code','com_shareReward','com_self','btn_global','btn_local','btn_friend','btn_friend1','btn_wxFriend','btn_bindSns','btn_search','btn_wechat_invite','img_red1','com_reddot'])this.ui.hide(v,name);for(const[name,label]of [['btn_addFriend','好友'],['btn_timeline','动态'],['btn_rank','排行榜']]){const button=this.ui.find(v,name);for(const n of button.querySelectorAll('.fg-text,.fg-richtext'))this.ui.renderText(n,label);this.ui.hide(button,'img_red1');this.ui.hide(button,'img_red2');}this.ui.text(v,'text_title',tab==='timeline'?'动态':tab==='rank'?'排行榜':'好友');this.ui.show(v,'group_no');this.ui.text(v,'text_des2',tab==='timeline'?this.assets.strings['10800055']:tab==='rank'?'暂无排行':this.assets.strings['10800038']);for(const[name,action]of [['btn_addFriend','friends'],['btn_timeline','friends:timeline'],['btn_rank','friends:rank'],['com_bottom/btn_close','close']])this.ui.action(v,name,action);this.ui.autoplay(v);return v;}
 album(){const v=this.host.show('PictureAlbumMainWindow',{},'album');for(const list of v.querySelectorAll('.fg-list'))list.replaceChildren();const main=this.ui.find(v,'com_mainPart');this.ui.hide(main,'icon_theme');this.ui.hide(main,'icon_logo');this.ui.text(main,'text_remaining_time','');this.ui.show(main,'text_complete_tip');this.ui.text(main,'text_complete_tip','画册尚未开启');const progress=this.ui.find(main,'progress_collect');this.ui.setProgress(progress,0,1);this.ui.text(progress,'title','0/0');this.ui.hide(v,'btn_limit');this.ui.hide(v,'btn_recycle');this.ui.hide(v,'com_closure/btn_left');this.ui.hide(v,'com_closure/btn_right');this.ui.action(v,'btn_recycle','unavailable:暂无可回收卡片');this.ui.action(main,'btn_tip','unavailable:画册尚未开启');this.ui.action(v,'com_closure/btn_close','close','返回棋盘');this.ui.autoplay(v);return v;}
 profile(){const v=this.host.show('PlayerInfoWindow',{controllers:{ctrl_type:'0'}},'profile'),g=this.host.engine;this.ui.text(v,'text_username','小新（本机）');this.ui.text(v,'text_map',g.mapConfig.name);this.ui.text(v,'title_05','地图');this.ui.text(v,'title_06','共同好友');for(const path of ['com_commonFriend','text_commonFriend','btn_id','btn_add','btn_delete','group_delete','com_sheildTips','com_PieceTips','icon_head1','icon_head2','icon_headSingle','title_06','title_09','com_pet'])this.ui.hide(v,path);for(const title of this.ui.find(v,'com_level').querySelectorAll('.fg-text'))this.ui.renderText(title,String(g.state.level));for(const[name,image]of [['com_shiled','assets/scene/shield.png'],['com_chess','assets/scene/shin-avatar.png'],['com_dice',this.ui.image('icon_dice.png')]]){const part=this.ui.find(v,name);if(part)for(const loader of part.querySelectorAll('.fg-loader'))if(/icon_/i.test(loader.dataset.name)||(this.ui.sanguoActivityIcon&&loader.dataset.name==='icon'))this.ui.setImage(loader,image);}this.ui.action(v,'btn_close','close','返回棋盘');this.ui.action(v,'btn_more','menu','菜单');return v;}
}
